#!/usr/bin/env node
/**
 * generate-segment-mapping.mjs
 *
 * Build-time script: scans insights content files and auto-generates
 * INSIGHTS_SEGMENT_LABELS mapping (slug → Chinese title) for the admin dashboard.
 *
 * Data source: apps/insights/content/en/*.mdx frontmatter → slug
 *              apps/insights/content/zh/{slug}.mdx frontmatter → Chinese title
 *
 * Run: node packages/scripts/generate-segment-mapping.mjs
 * Output: apps/admin/src/lib/segment-mapping.ts (auto-generated, do not edit manually)
 */

import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const ROOT = path.resolve(__dirname, '..', '..');
const BLOG_EN_DIR = path.join(ROOT, 'apps/insights/content/en');
const BLOG_ZH_DIR = path.join(ROOT, 'apps/insights/content/zh');
const REG_EN_DIR = path.join(ROOT, 'apps/regulations/content/en');
const REG_ZH_DIR = path.join(ROOT, 'apps/regulations/content/zh');
const OUTPUT_FILE = path.join(ROOT, 'apps/admin/src/lib/segment-mapping.ts');

/**
 * 仅在内容（忽略头部日期戳）真正变化时写文件。
 * 日期戳语义 = 「最后一次内容变更日期」，避免每次构建都把自动生成文件改脏。
 */
function writeIfChanged(file, content) {
  const stripDate = (s) => s.replace(/ at \d{4}-\d{2}-\d{2}/, ' at <DATE>');
  if (fs.existsSync(file) && stripDate(fs.readFileSync(file, 'utf-8')) === stripDate(content)) {
    console.log('  (内容无变化，保留原日期戳，跳过写入)');
    return false;
  }
  fs.writeFileSync(file, content, 'utf-8');
  return true;
}

/**
 * Parse frontmatter from an MDX file.
 * Returns the frontmatter fields as a map, or null if file doesn't exist / can't be parsed.
 */
function parseFrontmatter(filePath) {
  if (!fs.existsSync(filePath)) return null;
  const content = fs.readFileSync(filePath, 'utf-8');
  const match = content.match(/^---\n([\s\S]*?)\n---/);
  if (!match) return null;

  const fields = {};
  for (const line of match[1].split('\n')) {
    // 只取顶层 key: value（缩进行是多行值/列表项，跳过）
    const keyMatch = line.match(/^(\w+):\s*(.*)$/);
    if (!keyMatch) continue;
    let value = keyMatch[2].trim();
    // YAML 里 title 可以带引号也可以不带（投稿包两种都出现过）。
    // 旧版只认双引号写法，遇到无引号 title 就返回 undefined，
    // 进而让 cleanTitle 崩溃、整个 admin 构建失败（2026-11-05 实际发生）。
    if (
      (value.startsWith('"') && value.endsWith('"') && value.length >= 2) ||
      (value.startsWith("'") && value.endsWith("'") && value.length >= 2)
    ) {
      value = value.slice(1, -1);
    }
    if (value) fields[keyMatch[1]] = value;
  }
  return fields;
}

/**
 * Clean colons and em-dashes from a title (consistent with R08 rule).
 */
function cleanTitle(title) {
  if (typeof title !== 'string') return '';
  return title
    .replace(/\s*[:：]\s*/g, ' ')     // Replace colons (full/half-width) with space
    .replace(/\s*—\s*/g, ' ')          // Em-dash
    .replace(/\s*[-–]\s*/g, ' ')       // En-dash / hyphen
    .replace(/\s+/g, ' ')              // Collapse whitespace
    .trim();
}

// ── Build mapping ──

/**
 * 扫一个内容目录，返回 [{slug, enTitle, zhTitle}]。
 * insights 与 regulations 结构相同（content/en/*.mdx + content/zh/*.mdx），复用同一套解析。
 */
function scanContent(dirEn, dirZh, label) {
  if (!fs.existsSync(dirEn)) {
    console.warn(`  ⚠  ${label}: 目录不存在 ${dirEn}`);
    return [];
  }
  const entries = [];
  for (const file of fs.readdirSync(dirEn).filter(f => f.endsWith('.mdx')).sort()) {
    const slug = file.replace(/\.mdx$/, '');
    const enFm = parseFrontmatter(path.join(dirEn, file));
    const zhFm = parseFrontmatter(path.join(dirZh, file));
    if (!enFm || !enFm.title) {
      console.warn(`  ⚠  Skipping ${label}/${slug}: no English frontmatter title`);
      continue;
    }
    const enTitle = cleanTitle(enFm.title);
    const zhTitle = zhFm ? cleanTitle(zhFm.title) : enTitle; // fallback to English if no zh
    entries.push({ slug, enTitle, zhTitle });
  }
  return entries;
}

const entries = scanContent(BLOG_EN_DIR, BLOG_ZH_DIR, 'insights');
const regEntries = scanContent(REG_EN_DIR, REG_ZH_DIR, 'regulations');

// 两套 slug 若重名会互相覆盖 → 提前发现（实测当前 0 重叠，仅作护栏）
const dup = entries.map(e => e.slug).filter(s => regEntries.some(r => r.slug === s));
if (dup.length > 0) {
  console.warn(`  ⚠  ${dup.length} 个 slug 在 insights 与 regulations 中重名：${dup.slice(0, 3).join(', ')}`);
}

// ── Generate TypeScript file ──

const lines = [
  '// AUTO-GENERATED — do not edit manually',
  `// Generated by packages/scripts/generate-segment-mapping.mjs at ${new Date().toISOString().slice(0, 10)}`,
  `// Source: ${entries.length} insights + ${regEntries.length} regulations articles (content/en + content/zh)`,
  '',
  '/**',
  ' * Insights article slug → Chinese display name mapping.',
  ' * Used by the dashboard pathToBreadcrumb() to display Chinese path labels',
  ' * without requiring manual SEGMENT_LABELS entries.',
  ' */',
  'export const INSIGHTS_SEGMENT_LABELS: Record<string, string> = {',
];

for (const { slug, zhTitle } of entries) {
  const escaped = zhTitle.replace(/\\/g, '\\\\').replace(/`/g, '\\`').replace(/\$/g, '\\$');
  lines.push(`  '${slug}': \`${escaped}\`,`);
}

lines.push('};');
lines.push('');
lines.push('/**');
lines.push(' * Insights article slug → English display name mapping (for English locale).');
lines.push(' */');
lines.push('export const INSIGHTS_SEGMENT_LABELS_EN: Record<string, string> = {');

for (const { slug, enTitle } of entries) {
  const escaped = enTitle.replace(/\\/g, '\\\\').replace(/`/g, '\\`').replace(/\$/g, '\\$');
  lines.push(`  '${slug}': \`${escaped}\`,`);
}

lines.push('};');
lines.push('');
lines.push('/**');
lines.push(' * Regulations article slug → Chinese display name mapping.');
lines.push(' */');
lines.push('export const REGULATIONS_SEGMENT_LABELS: Record<string, string> = {');
for (const { slug, zhTitle } of regEntries) {
  const escaped = zhTitle.replace(/\\/g, '\\\\').replace(/`/g, '\\`').replace(/\$/g, '\\$');
  lines.push(`  '${slug}': \`${escaped}\`,`);
}
lines.push('};');
lines.push('');
lines.push('/**');
lines.push(' * Regulations article slug → English display name mapping (for English locale).');
lines.push(' */');
lines.push('export const REGULATIONS_SEGMENT_LABELS_EN: Record<string, string> = {');
for (const { slug, enTitle } of regEntries) {
  const escaped = enTitle.replace(/\\/g, '\\\\').replace(/`/g, '\\`').replace(/\$/g, '\\$');
  lines.push(`  '${slug}': \`${escaped}\`,`);
}
lines.push('};');

const output = lines.join('\n') + '\n';

// ── Write output ──

fs.mkdirSync(path.dirname(OUTPUT_FILE), { recursive: true });
writeIfChanged(OUTPUT_FILE, output);

console.log(`\n✅ Generated ${OUTPUT_FILE}`);
console.log(`   ${entries.length} insights + ${regEntries.length} regulations article mappings (slug → Chinese title)`);
